description:
创建 NodeEditor 页面，整合节点选择器、data.json 编辑器和 index.md 编辑器

组件结构 src/pages/NodeEditor.jsx：
```jsx
import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import NodeSelector from '../components/NodeSelector'
import JsonEditor from '../components/JsonEditor'
import MarkdownEditor from '../components/MarkdownEditor'

export default function NodeEditor() {
  const { slug } = useParams()
  const navigate = useNavigate()
  const [activeTab, setActiveTab] = useState('data')
  const [saveStatus, setSaveStatus] = useState('')

  const handleSave = (type) => {
    setSaveStatus(`${type === 'data' ? 'data.json' : 'index.md'} 已保存`)
    setTimeout(() => setSaveStatus(''), 2000)
  }

  return (
    <div className="flex flex-col h-screen">
      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 border-b border-[#2A2A28]">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/')}
            className="text-[#8A8A85] hover:text-[#F0EDE6] transition-colors"
          >
            ← 返回
          </button>
          <NodeSelector currentSlug={slug} onSelect={(s) => navigate(`/editor/${s}`)} />
        </div>
        {saveStatus && (
          <span className="text-sm text-[#C0392B]">{saveStatus}</span>
        )}
      </header>

      {/* Tabs */}
      <div className="flex border-b border-[#2A2A28]">
        <button
          onClick={() => setActiveTab('data')}
          className={`px-6 py-3 text-sm transition-colors ${
            activeTab === 'data'
              ? 'text-[#F0EDE6] border-b-2 border-[#C0392B]'
              : 'text-[#8A8A85] hover:text-[#F0EDE6]'
          }`}
        >
          data.json
        </button>
        <button
          onClick={() => setActiveTab('index-md')}
          className={`px-6 py-3 text-sm transition-colors ${
            activeTab === 'index-md'
              ? 'text-[#F0EDE6] border-b-2 border-[#C0392B]'
              : 'text-[#8A8A85] hover:text-[#F0EDE6]'
          }`}
        >
          index.md
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden p-6">
        {activeTab === 'data' ? (
          <JsonEditor key={slug} slug={slug} onSave={handleSave} />
        ) : (
          <MarkdownEditor key={slug} slug={slug} onSave={handleSave} />
        )}
      </div>
    </div>
  )
}
```
